package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.TlsWarnDaysVO;

class TlsWarnDaysValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of tls warn days of observed probe")
  void test_tls_warn_days_value_holder_assign_plain_value() {
    Object holder = new Object();
    TlsWarnDaysValueHolder<Object> value = new TlsWarnDaysValueHolder<>(holder);
    Assertions.assertSame(holder, value.tlsWarnDays(1), "Setters must return the holder");
    Assertions.assertTrue(value.getTlsWarnDaysValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getTlsWarnDays().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of tls warn days of observed probe")
  void test_tls_warn_days_value_holder_assign_value_object() {
    Object holder = new Object();
    TlsWarnDaysValueHolder<Object> value = new TlsWarnDaysValueHolder<>(holder);
    TlsWarnDaysVO vo = TlsWarnDaysVO.from(1);
    Assertions.assertFalse(value.getTlsWarnDaysValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.tlsWarnDays(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTlsWarnDaysValue().orElseThrow());
    Assertions.assertSame(holder, value.tlsWarnDays(Optional.empty()));
    Assertions.assertFalse(value.getTlsWarnDaysValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.tlsWarnDays(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTlsWarnDaysValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of tls warn days of observed probe against the original")
  void test_tls_warn_days_value_holder_read() {
    Object holder = new Object();
    TlsWarnDaysValueHolder<Object> value = new TlsWarnDaysValueHolder<>(holder);
    TlsWarnDaysVO vo = TlsWarnDaysVO.from(1);
    TlsWarnDaysVO other = TlsWarnDaysVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getTlsWarnDaysValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTlsWarnDays(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readTlsWarnDays(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.tlsWarnDays(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTlsWarnDays(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTlsWarnDays(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of tls warn days of observed probe")
  void test_tls_warn_days_value_holder_unset() {
    Object holder = new Object();
    TlsWarnDaysValueHolder<Object> value = new TlsWarnDaysValueHolder<>(holder);
    TlsWarnDaysVO vo = TlsWarnDaysVO.from(1);
    value.tlsWarnDays(vo);
    Assertions.assertSame(holder, value.unsetTlsWarnDaysIfMatches("tlsWarnDays_other"));
    Assertions.assertTrue(value.getTlsWarnDaysValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTlsWarnDaysIfMatches("tlsWarnDays"));
    Assertions.assertFalse(value.getTlsWarnDaysValue().isPresent(),
        "The field name must clear the value");
    value.tlsWarnDays(vo);
    Assertions.assertSame(holder, value.unsetTlsWarnDays());
    Assertions.assertFalse(value.getTlsWarnDaysValue().isPresent(), "Unset must clear the value");
  }
}
